#pragma once
#include "kstationMidiWrappersTask.h"
#include "kstationMidiEventTask.h"
#include "kstationControllerProgramLoadTask.h"
#include <optional>
namespace kstation {
class ControllerProgramTask final {
 using W=MidiWrapperTask;using WS=W::Stage;using H=MidiEventHelperTask;using HS=H::Stage;using C=MidiProgramCommitTask;using CS=C::Stage;
public:
 enum class Service:uint8_t{None,DspWrite,RefreshPanel,InitializeVoice,ReleaseVoices,RefreshDisplay};struct Request{Service service=Service::None;uint8_t bank=0,program=0,part=0;uint16_t address=0;uint32_t word=0;};explicit ControllerProgramTask(uint32_t payload):root_(W::Kind::Program),payload_(payload&0xffffff){}bool complete()const{return root_.complete()&&!helper_&&!commit_&&!load_;}Request request()const{if(load_){auto r=load_->request();using L=ControllerProgramLoadTask::Service;return {r.service==L::DspWrite?Service::DspWrite:r.service==L::RefreshPanel?Service::RefreshPanel:r.service==L::InitializeVoice?Service::InitializeVoice:r.service==L::ReleaseVoices?Service::ReleaseVoices:Service::None,root_.bank(),root_.program(),r.part,r.address,r.word};}if(!commit_||!commit_->awaitingChild())return {};return {commit_->child()==C::Child::Load?Service::None:Service::RefreshDisplay,root_.bank(),root_.program(),0,0,0};}bool resume(Service s){auto r=request();if(s==Service::None||r.service!=s)return false;if(load_)return load_->resume(s==Service::DspWrite?ControllerProgramLoadTask::Service::DspWrite:s==Service::RefreshPanel?ControllerProgramLoadTask::Service::RefreshPanel:s==Service::InitializeVoice?ControllerProgramLoadTask::Service::InitializeVoice:ControllerProgramLoadTask::Service::ReleaseVoices);return commit_->resume(commit_->child());}
 bool stackWrites()const{if(load_)return load_->stackWrites();if(helper_){auto s=helper_->stage();return s==HS::SaveInput||s==HS::SaveWord;}if(commit_)return commit_->stage()==CS::Load||commit_->stage()==CS::Display;auto s=root_.stage();return s==WS::Call||s==WS::CallProgram;}
 unsigned nextClocks(int previous=-1)const{if(request().service!=Service::None)return 0;if(load_)return load_->nextClocks(previous);if(helper_){switch(helper_->stage()){case HS::ReadChannel:case HS::ReadIndex:return 12;case HS::ReadProgramChannel:return 15;case HS::BindProgram:return 9;case HS::SaveInput:case HS::RestoreInput:case HS::SaveWord:case HS::RestoreWord:case HS::WriteChannel:return 6;case HS::Return:return 7;case HS::Complete:return 0;default:return 3;}}if(commit_){switch(commit_->stage()){case CS::WriteBank:return 9+bus(0xcd82,previous);case CS::WriteProgram:return 9+bus(0xcd83,previous);case CS::Load:return 5;case CS::Display:return 10;case CS::Return:return 7;case CS::AwaitChild:case CS::Complete:return 0;default:return 3;}}switch(root_.stage()){case WS::Call:case WS::CallProgram:return 10;case WS::ReadBank:return 12;case WS::WriteBank:return 9+bus(0xcbff,previous);case WS::ReadProgram:return 6;case WS::Return:return 7;case WS::AwaitChild:case WS::Complete:return 0;default:return 3;}}
 template<class R,class Q>unsigned advanceBefore(unsigned budget,R&&read,Q&&write,int previous=-1){auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;if(load_){auto used=load_->advanceBefore(cost,read,write,previous);if(load_->complete()){load_.reset();commit_->resume(C::Child::Load);}return used;}if(helper_){auto ok=helper_->advance([&](H::Read f){return read(f==H::Read::ProgramChannel?0xbb16:0xcad5,1,cost);},[&](H::Write,uint32_t v){write(helper_->address(),v,1,cost);});if(!ok)return 0;if(helper_->complete()){bool match=helper_->matches();helper_.reset();root_.resume(W::Child::Match,match?0:0xff);}return cost;}if(commit_){bool ok=commit_->advance([&](uint32_t address,bool bank){write(address,bank?root_.bank():root_.program(),1,cost);});if(!ok)return 0;if(commit_->awaitingChild()&&commit_->child()==C::Child::Load)load_.emplace();if(commit_->complete()){commit_.reset();root_.resume(W::Child::Program,0);}return cost;}bool ok=root_.advance([&](uint32_t addr){return read(addr?addr:payload_,1,cost);},[&](uint32_t addr,uint8_t v){write(addr,v,1,cost);});if(!ok)return 0;if(root_.awaitingChild()){if(root_.child()==W::Child::Match)helper_.emplace(H::Kind::ChannelMatch);else if(root_.child()==W::Child::Program)commit_.emplace(root_.bank());}return cost;}
private:static unsigned bus(uint32_t a,int previous){return (previous&1)||a!=uint32_t(previous|1)?3:0;}W root_;uint32_t payload_;std::optional<H>helper_{};std::optional<C>commit_{};std::optional<ControllerProgramLoadTask>load_{};
};
}
